(function () {
  var container = document.querySelector(".post-stream-container");
  var sentinel = document.querySelector(".post-stream-sentinel");
  var loading = document.querySelector(".post-stream-loading");
  if (!container || !sentinel) return;

  var busy = false;

  function nextUrl() {
    return container.getAttribute("data-next-url");
  }

  function setLoading(on) {
    if (loading) loading.hidden = !on;
  }

  function loadMore() {
    var url = nextUrl();
    if (busy || !url) return;
    busy = true;
    setLoading(true);

    fetch(url, { credentials: "same-origin" })
      .then(function (res) {
        if (!res.ok) throw new Error("HTTP " + res.status);
        return res.text();
      })
      .then(function (html) {
        var doc = new DOMParser().parseFromString(html, "text/html");
        var incoming = doc.querySelector(".post-stream-container");
        if (!incoming) throw new Error("No post container in response");

        var frag = document.createDocumentFragment();
        incoming.querySelectorAll(".post-entry").forEach(function (post) {
          frag.appendChild(document.importNode(post, true));
        });
        container.appendChild(frag);

        var next = incoming.getAttribute("data-next-url");
        if (next) {
          container.setAttribute("data-next-url", next);
        } else {
          container.removeAttribute("data-next-url");
          observer.disconnect();
        }

        busy = false;
        setLoading(false);

        // In case the sentinel is still on-screen after appending, keep going.
        if (nextUrl() && isInView(sentinel)) loadMore();
      })
      .catch(function () {
        // Stop trying on error; leave the noscript fallback path intact.
        busy = false;
        setLoading(false);
        observer.disconnect();
      });
  }

  function isInView(el) {
    var rect = el.getBoundingClientRect();
    return rect.top <= (window.innerHeight || document.documentElement.clientHeight);
  }

  var observer = new IntersectionObserver(
    function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) loadMore();
      });
    },
    { rootMargin: "400px 0px" }
  );

  if (nextUrl()) {
    observer.observe(sentinel);
  }
})();
